BASE=Path(__file__).resolve().parents[1];OUT=BASE/'.cache/batch200/drafts/rewrite_vid'
S=lambda w:'https://www.etymonline.com/word/'+w
O=lambda w:'https://www.oxfordlearnersdictionaries.com/definition/english/'+w
K=lambda w:'https://en.wiktionary.org/wiki/'+w
W=[
E('like','/laɪk/','喜欢；像、如同；点赞','I like this song 是这首歌合我心意；This song sounds like jazz 是它听起来像爵士乐。同一拼写，前者说感受，后者说相似，先看句子结构。','“喜欢”的动词接古英语 līcian“使人愉快、合意”；“相像”的形容词等接古英语 ġelīc，并受到古诺尔斯语同源形式影响。两支更早都与形态、相似相关，但由相似到合意的具体语义过程不完全确定，不能当成现代英语里的直接派生。',[['古英语两支：līcian；ġelīc','使人愉快、合意；相似、同样'],['中古英语 liken；lik／like','动词的喜欢义；相似义及相关介词用法'],['现代英语 like','喜欢、像；后发展出网络点赞等用法']],'古老动词的表达方向更接近“这件事令我满意”，后来常用“我喜欢这件事”。现代动词 like 后可接名词或 doing；表示像时，like 把两样东西作比较。I’d like 则是较客气地说想要。社交平台的 a like 是一次点赞。','like doing；would like to do；look like；What is it like?〔询问怎么样〕；give a post a like。','What does she like? 问她喜欢什么；What is she like? 问她是怎样的人。like 与 as 都能比较，但 as a teacher 常表示身份“作为教师”，like a teacher 表示“像教师一样”。',('I like walking through the park before work.','我喜欢上班前在公园里散步。'),('The cloud looks like a sleeping cat.','那朵云看起来像一只睡着的猫。'),('I would like to ask one more question.','我想再问一个问题。'),('The photograph received hundreds of likes.','这张照片获得了几百个赞。'),sources=[S('like'),K('like'),O('like_1')]),
E('such','/sʌtʃ/','这样的；如此的；这一类的','前面说了一种情况，后面说 such problems，就像用手指回去：“这一类问题”。它也能把程度推高：such a lovely day，是这么美好的一天。','来自古英语 swilc／swylc，经中古英语 swich 等形式变为 such。更早是相当于“如此＋形态”的日耳曼语组合，与 so 和 like 的相似义相关；今天不能按字母拆成英语 so 加 like。',[['早期日耳曼语“如此”与“形态、相似”的材料','相当于 so 与 like 的更早同源成分'],['古英语 swilc／swylc → 中古英语 swich','那样的、同类的'],['英语 such','指示类别，也加强名词短语所表达的程度']],'such a problem 是这样一个问题，such problems 是这类问题。such as 用例子把类别说明白；such…that… 则能说明程度大到产生某个结果。','such a good idea；such useful advice；such as；no such thing。','so 通常直接加强形容词或副词：so useful；such 通常带着名词短语：such useful advice。单数可数名词常用 such a/an… 的顺序。',('We need a clear process for dealing with such problems.','我们需要一套明确流程来处理这类问题。'),('It was such a quiet morning that we could hear the birds across the river.','那是一个如此安静的早晨，我们能听见河对岸的鸟鸣。'),sources=[S('such'),O('such'),K('such')]),
E('likely','/ˈlaɪkli/','很可能的；可能会；合适或有希望的','看着乌云，你觉得雨很可能要来了。likely 表示事情符合眼前线索，看起来像会发生，但还没有成为确定事实。','中古英语已有 likely／likly，历史与古诺尔斯 líkligr“可能的”和古英语相关 ġelīclic 形式相连；借入与本族形式的作用有不同分析。可按 like“相似、看来如此”加形容词性 -ly 理解，不能当作“喜欢地”。',[['古英语 ġelīclic；古诺尔斯 líkligr 等同源形式','相称、合适；看起来可能'],['中古英语 likely／likly','看起来可信、可能'],['英语 likely','很可能；也说合适、有希望的候选者或地点']],'be likely to do 是很可能做某事；It is likely that… 后面接完整句子。likely 也可作副词，如 will likely arrive。a likely candidate 则常是看起来合适或有希望的人选。','be likely to；it is likely that；most likely；a likely explanation。','likely 不说明一个固定百分比。possible 只说存在可能，likely 通常判断发生的希望更大；likable 才是讨人喜欢。',('The roads are likely to be busy this evening.','今晚道路很可能会很拥堵。'),('A loose cable is the most likely explanation for the problem.','电缆松动是这个问题最可能的原因。'),sources=[S('likely'),K('likely'),'https://www.oxfordlearnersdictionaries.com/definition/english/likely_1']),
E('unlikely','/ʌnˈlaɪkli/','不太可能的；不像会出现的；出人意料的','按照已有线索，你原本不会押它发生，就是 unlikely。一个不被看好的人最终成了英雄，也会被叫 an unlikely hero。','否定 un- 加 likely，中古英语已有 unlikli 等形式。现代既否定事件发生的可能，也可描述某人与角色或某个组合不符合常规预期。',[['英语 likely；否定 un-','很可能、符合预期；不'],['中古英语 unlikli → 英语 unlikely','不大可能；后来也形容出乎预期的人或组合']],'unlikely to win 是赢的机会小；an unlikely friendship 是起初让人意外的友谊，不是说这段友谊一定虚假。语义要看它修饰事件概率还是人物组合。','be unlikely to；highly unlikely；an unlikely hero；an unlikely partnership。','unlikely 不等于 impossible。前者留有可能，后者通常直接排除可能。unlike 则多表示不相似，没有 -ly 这层可能性判断。',('The shop is unlikely to reopen before Monday.','这家店周一之前不太可能重新营业。'),('The two rivals formed an unlikely friendship.','这两个对手建立了一段令人意外的友谊。'),sources=[S('unlikely'),K('unlikely'),O('unlikely')]),
E('likelihood','/ˈlaɪklihʊd/','可能性；可能发生的程度','likely 是“很可能”；likelihood 把这个判断变成可以讨论的一件事：发生的可能性有多大。','likely 加表示状态的 -hood，中古英语已有 liklihode。早期也表示相似，后来重心转为事情看起来会发生的可能性。',[['英语 likely；-hood','看起来相似、可能；状态后缀'],['中古英语 liklihode → 英语 likelihood','早期相似义；发展为发生的可能性']],'reduce the likelihood of errors 就是降低出错的可能。in all likelihood 常表示十有八九，而不是数学上百分之百。日常阅读先把它理解为“可能性”即可。','the likelihood of doing；the likelihood that…；in all likelihood；a high likelihood。','likeness 是相像，likelihood 是可能性。统计学 likelihood“似然”有专门定义，不应把日常可能性与技术概念不加区分地互换。',('Clear labels reduce the likelihood of mistakes.','清楚的标签能降低出错的可能性。'),('In all likelihood, the meeting will finish before noon.','会议十有八九会在中午之前结束。'),sources=[S('likelihood'),K('likelihood'),O('likelihood')]),
E('unlike','/ʌnˈlaɪk/','不像；与……不同；网络中也指取消点赞','把两样东西摆在一起，指出它们不同，可以用 unlike。Unlike the old model… 就是把新旧型号放到对照中。','相似义的否定形式在古英语 unlīc／ungelīc 已有，经中古英语进入现代；表面可拆 un-＋like。动词“停止喜欢、取消点赞”是逆转性 un- 加动词 like 的另一条构词支线。',[['古英语 unlīc／ungelīc；另有逆转 un-＋动词 like','不同、不相似；撤去喜欢这一动作'],['中古英语相异形式 → 英语 unlike；动词支线另行发展','主要表示差异；后也用于取消已点的赞']],'unlike 后常接比较对象。It is unlike her to be late 不是批评她长得不像谁，而是说迟到不符合她平常的作风。网上 unlike a post 则是撤销赞。','unlike the others；quite unlike；it is unlike someone to do；unlike a post。','dislike 是不喜欢；unlike 的常见介词义是不同于。网络动词 unlike 撤回一个赞，也不一定表示讨厌内容。',('Unlike the old model, this camera fits in my pocket.','与旧型号不同，这台相机能放进我的口袋。'),('It is unlike Maya to miss a deadline.','错过截止时间不像玛雅平时的作风。'),('I accidentally liked the post and then unliked it.','我不小心给那条帖子点了赞，随后又取消了。'),sources=[S('unlike'),K('unlike'),O('unlike')]),
E('alike','/əˈlaɪk/','相像的；同样地；两者都','两把钥匙并排放着，看起来很像，可以说 they look alike。重点是它们彼此相像，不需要在 alike 后再补一个比较对象。','由古英语 onlīc／anlīc、ġelīc 及相应副词形式，经中古英语若干形式汇合；古诺尔斯同源词也有影响。今天可辅助看成 a-＋like，但开头 a- 不是否定。',[['古英语 onlīc／anlīc、ġelīc 等；古诺尔斯相关形式','彼此相似；以相同方式'],['中古英语 alich／alyke 等 → 英语 alike','形容相像；作副词表示同样、双方都']],'look alike 常说外形相似，think alike 是想法相近。children and adults alike 意思是儿童和成年人都包括在内。形容词 alike 通常放在 be、look 等之后，不说 two alike keys。','look alike；think alike；treat people alike；young and old alike。','like 后可以接比较对象：A is like B。alike 通常概括复数主体：A and B are alike；不要再写 alike B。',('The twins look alike, but their voices are different.','这对双胞胎长得相像，但声音不同。'),('The exhibition appealed to children and adults alike.','这场展览让儿童和成年人都很感兴趣。'),sources=[S('alike'),K('alike'),O('alike')]),
E('likewise','/ˈlaɪkwaɪz/','同样地；也；我也是','前面说了一件事，后面的人或事情也一样，就可以用 likewise 把两边接上。它有“照同样方式、同样情况”的意味。','来自中古英语短语 in like wise，逐渐缩为 likewise。wise 在这里是旧名词“方式”，与形容词 wise“聪明的”不能按现代字面混拆。',[['英语 like；旧名词 wise','相同、相似；方式'],['中古英语 in like wise → likewise','以同样的方式'],['英语 likewise','同样地、也；也可单独作回应']],'The second group did likewise 是第二组也照着做了。别人说 Nice to meet you，你回 Likewise，是把同样的礼貌或感受还给对方。','do likewise；and likewise；Likewise!〔同样、我也是〕。','also 只是添加信息；likewise 更容易突出前后相同或平行。它不是“像个聪明人一样”。',('The first team checked every measurement, and the second team did likewise.','第一组核对了每项测量结果，第二组也照做了。'),('The new design saves space and is likewise easier to clean.','新设计节省空间，同时也更容易清洁。'),sources=[S('likewise'),K('likewise'),O('likewise')]),
E('liking','/ˈlaɪkɪŋ/','喜爱；偏好；满意','某种口味正合你的胃口，可以说 it is to your liking；见到一个人很快产生好感，则是 take a liking to。','古英语已有动词 līcian 对应的名词 līcung“愉快、喜爱”，经中古英语 likinge 到 liking。现代也可按 like 去 e 加 -ing 理解，不能说名词直到今天才由进行时临时变来。',[['古英语 līcian → līcung','使人愉快；由动词形成喜爱、愉快的名词'],['中古英语 likinge → 英语 liking','喜爱、偏好；现代也有 like 的 -ing 动词形式']],'a liking for puzzles 是对谜题的爱好；too sweet for my liking 是甜得超过我的喜好。这些表达把个人感受当作名词来说。','a liking for；take a liking to；to someone’s liking；for my liking。','liking 不表示相似，那是 likeness。I’m liking it 在口语里可强调目前越来越享受，但表达一般喜好通常说 I like it。',('She developed a liking for old maps.','她渐渐喜欢上了旧地图。'),('The music was a little too loud for my liking.','这音乐对我来说稍微太响了。'),sources=[S('liking'),K('liking'),O('liking')]),
E('dislike','/dɪsˈlaɪk/','不喜欢；反感；厌恶感','食物、行为或环境让你不乐意接近，可以用 dislike。它明确表达负面感受，程度又不必强到 hate。','英语 dis- 与动词 like 组合，16 世纪已有记录，后来也作名词。它将外来的否定前缀与英语本族词放在一起，不是一个完整拉丁词直接借入。',[['英语动词 like；否定 dis-','喜欢；相反、不'],['英语 dislike 动词〔16 世纪〕 → 相应名词','不喜欢；对人或事的反感']],'dislike doing something 是不喜欢做某事。作名词时 a dislike of noise 是对噪声的反感；likes and dislikes 则是各种好恶。','dislike waiting；a strong dislike of；take a dislike to；likes and dislikes。','dislike 不等于 hate 那么强烈；unlike 主要用于比较差异。喜欢与不喜欢说的是感受，相像与不像说的是比较。',('I dislike being interrupted while I am reading.','我不喜欢看书时被打断。'),('He made no secret of his dislike of noisy restaurants.','他毫不掩饰自己对吵闹餐馆的反感。'),sources=[S('dislike'),K('dislike'),O('dislike_1')]),
E('likeness','/ˈlaɪknəs/','相似；肖像；像某人的形象','一幅画像让你一眼认出那个人，就是画出了他的 likeness。这个词既能说“像的程度”，也能说呈现那种相像的画像或形象。','古英语 ġelīcness／līcness 已有相像、形象等义，经中古英语 liknesse 进入现代；相当于 like“相像”加 -ness，不是由“喜欢”派生。',[['古英语 ġelīc；-ness 类名词后缀','相像；性质、状态'],['古英语 ġelīcness／līcness → 中古英语 liknesse','相似；图像、形象'],['英语 likeness','相似之处；人的肖像、外形再现']],'bear a likeness to someone 是长得像某人；a good likeness 常说画得很像的肖像。这里的 good 主要评价像不像，未必评价绘画风格是否华丽。','a striking likeness；bear a likeness to；capture someone’s likeness；a good likeness。','likeness 说相似或形象，liking 说喜爱，likelihood 说可能性。看到后缀前那几个字母一样，仍要确认是哪一种意思。',('There is a striking likeness between the two sisters.','这对姐妹长得非常相像。'),('The artist captured her likeness in a quick sketch.','画家用一幅速写画出了她的神态容貌。'),sources=[S('likeness'),K('likeness'),O('likeness')]),
E('liken','/ˈlaɪkən/','把……比作；认为……相像','讲一个抽象系统时，把它比作交通网络，让人一下看明白，就是 liken A to B。你是在建立类比，不是在说喜欢 A。','中古英语 liknen／liken 来自相似义的 lik 加动词词尾，接古英语 ġelīc。现代可按 like〔相像〕＋-en 理解，常用意义固定为拿两样东西相比。',[['古英语 ġelīc → 中古英语 lik','相似、相像'],['中古英语 liken／liknen → 英语 liken','比较、认为相似；现代常说把某物比作另一物']],'liken 常见于报道、评论和解释。主语是作比较的人，被动式 be likened to 则把被比较的东西放在前面。类比抓住某个共同点，不要求两者完全相同。','liken A to B；be likened to；critics likened…to…。','like 作动词通常是喜欢；liken 是作比较。compare 范围更宽，可以比较不同点；liken 通常强调相似之处。',('The teacher likened the internet to a network of roads.','老师把互联网比作道路网络。'),('Her clear writing has been likened to a conversation with a patient teacher.','她清晰的文字被比作与一位耐心老师的交谈。'),sources=[S('liken'),K('liken'),O('liken')]),
E('likable','/ˈlaɪkəbəl/','讨人喜欢的；让人容易产生好感的','一个人未必完美，但相处时真诚、有趣，让你愿意继续认识，就可以叫 likable。说的是容易赢得好感。','like〔喜欢〕加 -able，表示容易被喜欢。likable 尤见北美英语；likeable 尤见英国英语，两种拼写含义和读音相同，本条一起说明。',[['英语 like；-able','喜欢；可被、容易被'],['英语 likable／likeable','容易让人喜欢的']],'常形容人、小说人物或个性。a likable villain 可以是做坏事却让观众觉得有魅力的反派；这个词不自动保证其品德正确。','a likable person；a likable character；warm and likable。','likable 说讨人喜欢；likely 说可能发生。popular 是实际受到很多人欢迎，likable 是容易让人产生好感的特质，两者不必同时存在。',('She is a likable colleague who makes new staff feel welcome.','她是一位讨人喜欢的同事，总让新员工感到受欢迎。'),('The novel has a flawed but likable main character.','小说的主人公有缺点，却很讨人喜欢。'),sources=[O('likable'),K('likable'),K('likeable')]),
E('unlikable','/ʌnˈlaɪkəbəl/','不讨人喜欢的；令人难以产生好感的','一个故事人物总让读者不舒服、难以亲近，就可能被评价为 unlikable。它说的是人的观感，不是精确给人判定道德好坏。','否定 un- 加 likable；也写 unlikeable，后一形式对应保留 e 的 likeable。两种拼写的读音和核心意思相同。',[['英语 likable／likeable；否定 un-','讨人喜欢的；不'],['英语 unlikable／unlikeable','不容易让人喜欢的']],'常用于评论人物、行为或个性。an unlikable character 可以是作者刻意塑造的人物，不代表这本小说不好读，也不代表人物必然扁平。','an unlikable character；an unlikable personality；seem unlikable。','unlikable 不等于 unlikely“可能性小”，也不等于 unlike“与……不同”。它是对好感的评价，可能因观察者而异。',('The actor makes an unlikable character surprisingly interesting.','这位演员把一个不讨人喜欢的人物演得出奇地有意思。'),('His constant boasting made him seem unlikable at first.','他不停地吹嘘，起初让人觉得他不太讨喜。'),sources=[K('unlikable'),K('unlikeable'),'https://www.merriam-webster.com/dictionary/unlikable']),
]
names=[w['word'] for w in W]
cat=next(x for x in json.loads((BASE/'.cache/catalog.json').read_text()) if x['id']=='B3718')
